subroutine get_ui_input_presentation(executable, program_name, input_key, label, help, placeholder, units, visibility, found)
    character(len=*),              intent(in)  :: executable, program_name, input_key
    character(len=:), allocatable, intent(out) :: label, help, placeholder, units
    integer,                       intent(out) :: visibility
    logical,                       intent(out) :: found
    label = ''
    help = ''
    placeholder = ''
    units = ''
    visibility = UI_VIS_DEVELOPER
    found = .false.
    select case(trim(executable)//'/'//trim(program_name))
    case('simple_exec/abinitio3D')
        select case(trim(input_key))
        case('vol1')
            found = .true.
            label = 'Starting template volume'
            help = 'Starting reference volume  for particle matching'
            placeholder = 'input starting volume e.g. vol.mrc'
            units = ''
            visibility = UI_VIS_DEVELOPER
        case('center')
            found = .true.
            label = 'Center reference volume(s)'
            help = 'Center reference volume(s) by their center of gravity and map shifts back to the particles(yes|no){no}'
            placeholder = '(yes|no){no}'
            units = ''
            visibility = UI_VIS_DEVELOPER
        case('pgrp')
            found = .true.
            label = 'Point-group symmetry'
            help = 'Point-group symmetry of particle(cn|dn|t|o|i){c1}'
            placeholder = 'point-group(cn|dn|t|o|i){c1}'
            units = ''
            visibility = UI_VIS_STANDARD
        case('pgrp_start')
            found = .true.
            label = 'Initital point-group symmetry'
            help = 'Initial point-group symmetry(cn|dn|t|o|i){c1}'
            placeholder = 'point-group(cn|dn|t|o|i){c1}'
            units = ''
            visibility = UI_VIS_DEVELOPER
        case('cavg_ini')
            found = .true.
            label = '3D initialization on class averages'
            help = '3D initialization on class averages(yes|no){no}'
            placeholder = '(yes|no){no}'
            units = ''
            visibility = UI_VIS_DEVELOPER
        case('cavg_ini_ext')
            found = .true.
            label = 'External class-average 3D initialization'
            help = 'Use existing ptcl3D orientations and state assignments from a prior abinitio3D_cavgs run; skips the symmetry-search stage(yes|no){no}'
            placeholder = '(yes|no){no}'
            units = ''
            visibility = UI_VIS_DEVELOPER
        case('nsample')
            found = .true.
            label = 'Number of particles to sample'
            help = 'Number of particles to sample each iteration'
            placeholder = '# particles to sample'
            units = ''
            visibility = UI_VIS_STANDARD
        case('nstages')
            found = .true.
            label = 'Last ab initio stage to run'
            help = 'Last abinitio3D stage to run; default is 5 for multivol_mode=independent and 8 otherwise; independent mode writes final volumes at its last stage'
            placeholder = 'last stage'
            units = ''
            visibility = UI_VIS_DEVELOPER
        case('nstates')
            found = .true.
            label = 'Number of states'
            help = 'Number of conformational/compositional states to reconstruct'
            placeholder = '# states to reconstruct'
            units = ''
            visibility = UI_VIS_STANDARD
        case('state')
            found = .true.
            label = 'Continuation state label'
            help = 'State label to select from an existing multi-state abinitio3D project and continue as a single-state stage-5 search'
            placeholder = 'state label'
            units = ''
            visibility = UI_VIS_DEVELOPER
        case('multivol_mode')
            found = .true.
            label = 'Multi-volume ab initio mode'
            help = 'Multi-volume ab initio mode(single|independent|docked){single}'
            placeholder = '(single|independent|docked){single}'
            units = ''
            visibility = UI_VIS_DEVELOPER
        case('objfun_den')
